#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '../web/public/js/player');
const order = ['01-core-hls.js', '02-chat-colors.js', '03-socket-chat.js', '04-chat-input.js', '05-video-controls.js', '06-pip-cast.js', '07-chat-context.js', '08-autopilot.js', '09-overlays.js', '10-page-actions.js'];
let out = '/* AUTO-GENERATED by scripts/bundle-player.js — edit files in web/public/js/player/ then re-run */\n';
for (const f of order) {
  out += fs.readFileSync(path.join(dir, f), 'utf8');
  if (!out.endsWith('\n')) out += '\n';
}
const dest = path.join(__dirname, '../web/public/js/player.js');
fs.writeFileSync(dest, out);
console.log('Wrote', dest, out.split(/\n/).length, 'lines');
